let view='',settings={},targets=[],activeJob=null,page=1,summaryPage=1,filters={},selectedTargets=new Set(),selectedJobs=new Set(),selectedDatasets=new Set(),wizard={step:1,times:'08:00',crs:'WGS84',mode:'exact',candidates:5,date:new Date().toLocaleDateString('en-CA'),directions:['outbound'],source_point_ids:[],schedule:[],schedule_template:'',schedule_adjusted:false,schedule_window_confirmed:false,data_use:'unmarked',estimate_seconds:0.75,window_minutes:30},timer;
const DRAFT_KEY='traffic-accessibility-new-task-draft-v2';
function restoreWizardDraft(){try{const saved=JSON.parse(localStorage.getItem(DRAFT_KEY)||'null');if(saved&&typeof saved==='object'&&Array.isArray(saved.schedule)){wizard={...wizard,...saved};wizard.capacity=null;wizard.stats=saved.stats||null;return true}}catch(_){/* local storage can be unavailable or contain an old draft */}return false}
