function jobTable(rows,selectable=false){return rows.length?`<div class="table-wrap"><table><thead><tr>${selectable?'<th>选择</th>':''}<th>任务名称</th><th>创建时间</th><th>数据用途</th><th>状态</th><th>已处理 / 总条数</th><th>成功 / 失败</th><th>操作</th></tr></thead><tbody>${rows.map(j=>{const active=['queued','running','scheduled'].includes(j.status);return `<tr>${selectable?`<td><input class="job-check" type="checkbox" data-action="toggle-job" data-id="${j.id}" aria-label="选择任务 ${esc(j.name)}" ${active?'disabled title="请先暂停任务"':''} ${selectedJobs.has(j.id)?'checked':''}></td>`:''}<td><a href="#job/${j.id}">${esc(j.name)}</a></td><td>${esc(new Date(j.created).toLocaleString())}</td><td>${esc(dataUseLabels[j.data_use||'unmarked'])}</td><td>${badge(j.status)}</td><td>${j.success+j.failed} / ${j.total}<br><progress class="progress-inline" value="${j.success+j.failed}" max="${j.total||1}"></progress></td><td>${j.success} / ${j.failed}</td><td><a href="#job/${j.id}">打开任务</a></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">还没有分析任务。导入点位后即可开始。</div>'}
async function route(){view=(location.hash.slice(1)||'home').split('/')[0];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+view));$('#breadcrumb').textContent='工作空间 / '+({home:'首页',new:'新建分析任务',jobs:'任务中心',targets:'目标地点',data:'数据管理',usage:'地图查询记录',settings:'系统设置'}[view]||'任务详情');try{if(view==='home')await home();else if(view==='new')await renderWizard();else if(view==='jobs')await jobs();else if(view==='targets')await targetPage();else if(view==='data')await dataPage();else if(view==='usage')await usagePage();else if(view==='settings')await settingsPage();else if(view==='job'){page=1;filters={};await jobPage(location.hash.split('/')[1])}else location.hash='home'}catch(e){toast(e.message)}}
function keyGuide(){return `<section class="key-guide" aria-labelledby="key-guide-title"><h2 id="key-guide-title">开始真实采集：先申请高德 API Key</h2><ol><li><b>01 · 登录</b><p>打开高德开放平台控制台，注册或登录开发者账号。</p></li><li><b>02 · 创建应用</b><p>进入“应用管理”，点击“创建新应用”，填写应用信息。</p></li><li><b>03 · 添加 Key</b><p>在应用中点击“添加 Key”，服务平台选择 <strong>Web 服务</strong>。</p></li><li><b>04 · 配置本软件</b><p>复制 Key 到“系统设置”并保存；新建任务选择高德服务。正式采集前核对账户权限、配额并小规模试采。</p></li></ol><div class="toolbar"><a href="https://console.amap.com/" target="_blank" rel="noopener noreferrer">打开高德控制台</a><a href="https://lbs.amap.com/api/webservice/create-project-and-key" target="_blank" rel="noopener noreferrer">查看官方申请说明</a><a class="primary key-setup" href="#settings">前往系统设置</a></div><p>Key 只需填写在本机设置中，请妥善保管。${settings.has_key===null?'系统凭据库正在读取；若系统要求授权，请完成后刷新页面。':settings.has_key?'已保存 Key，仍需通过真实查询确认权限。':'尚未保存 Key；模拟模式仅用于测试流程。'}</p></section>`}
async function home(){const [d,j]=await Promise.all([api('/dashboard'),api('/jobs')]);$('#main').innerHTML=head('交通可达性分析','从坐标出发，比较不同目的地的驾车距离与时间。',btn('新建分析任务','new','','primary'))+keyGuide()+`<div class="metrics">${metric(d.jobs,'历史任务')}${metric(d.points,'导入点位（含异常）')}${metric(d.routes,'已完成结果（含模拟）')}${metric(d.calls,'地图查询次数')}</div><div class="hero"><div class="hero-copy"><h2>批量坐标，<br>清晰的可达性结果。</h2><p class="muted">导入 Excel 或 CSV，选择目标地点，后台计算并保存每一条结果。暂停之后，随时继续。</p>${btn('导入数据并开始','new','','primary')} <a class="subtle-link" href="/api/sample/xlsx">下载测试 Excel</a></div><div class="route-art" aria-label="起点与目标连接示意图"><svg viewBox="0 0 450 280" fill="none"><path d="M70 205L170 160L235 70M170 160L340 95M170 160L365 220" stroke="#002FA7" stroke-width="2"/><path d="M70 205L235 70M70 205L340 95M70 205L365 220" stroke="#002FA7" stroke-opacity=".25" stroke-dasharray="5 5"/><g fill="white" stroke="#002FA7" stroke-width="2"><circle cx="70" cy="205" r="7"/><circle cx="235" cy="70" r="5"/><circle cx="340" cy="95" r="5"/><circle cx="365" cy="220" r="5"/></g></svg><span class="caption">起点 → 目标地点 · 路线连接示意，非真实地图</span></div></div><div class="panel flush" style="margin-top:26px"><div class="panel-head"><h2>最近任务</h2><a href="#jobs">查看全部</a></div>${jobTable(j.slice(0,5))}</div>`}
async function jobs(){const rows=await api('/jobs');const available=new Set(rows.filter(j=>!['queued','running','scheduled'].includes(j.status)).map(j=>j.id));selectedJobs=new Set([...selectedJobs].filter(id=>available.has(id)));$('#main').innerHTML=head('任务中心','结果自动保存在本机，未完成的任务可以继续。',btn('新建分析任务','new','','primary'))+`<div class="selection-toolbar"><span><b id="job-selected-count">${selectedJobs.size}</b> 个任务已选择</span><div>${btn('选择全部可删除任务','select-all-jobs')} ${btn('清空选择','clear-jobs')} ${btn('删除选中任务','bulk-delete-jobs',selectedJobs.size?'':'disabled','danger')}</div></div><p class="muted batch-note">正在等待或计算的任务不能删除，请先打开任务并暂停。</p><div class="panel flush" id="job-list">${jobTable(rows,true)}</div>`}
