async function resultTable(){const r=await api(`/jobs/${activeJob.id}/results?${query()}`);$('#results').innerHTML=r.rows.length?`<div class="table-wrap"><table><thead><tr><th>方向</th><th>点位 ID / 名称</th><th>原始经纬度 / 坐标系</th><th>目标 / 经纬度</th><th>直线距离（km）</th><th>驾车距离（km）</th><th>预计耗时（分钟）</th>${activeJob.config.collection_mode==='scheduled'?'<th>计划时间（北京时间）</th>':''}<th>实际请求时间（北京时间）</th><th>数据类型</th><th>状态</th><th>详情</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.direction==='inbound'?'返程':'去程'}</td><td>${esc(x.point_id)}<br>${esc(x.point_name)}</td><td>${x.origin_lon}, ${x.origin_lat}<br>${esc(x.origin_crs)}</td><td>${esc(x.target_name)}<br>${x.target_lon}, ${x.target_lat}</td><td>${fmt(x.straight_km)}</td><td>${fmt(x.distance_meters,1000)}</td><td>${fmt(x.duration_seconds,60)}</td>${activeJob.config.collection_mode==='scheduled'?`<td>${esc(x.departure.replace('T',' ').replace('+08:00',''))}</td>`:''}<td>${x.requested_at?esc(new Date(x.requested_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})):'—'}</td><td>${esc(types[x.traffic_type]||'—')}<br>${esc(providerName(x.provider))}${x.cache_hit?' · 复用已有结果':''}</td><td>${badge(x.status)}</td><td title="${esc(x.request_coords)}">${esc(x.error||x.fetched_at||x.calculated_at||'—')}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>共 ${r.total.toLocaleString()} 条 · 第 ${page} / ${Math.ceil(r.total/50)} 页</span><div>${btn('上一页','prev',page===1?'disabled':'')} ${btn('下一页','next',page*50>=r.total?'disabled':'')}</div></div>`:'<div class="empty">暂无符合条件的结果。任务准备中时请稍后点击「筛选」刷新。</div>'}
