async function dataPage(){const rows=await api('/datasets');const available=new Set(rows.filter(d=>!d.job_count).map(d=>d.id));selectedDatasets=new Set([...selectedDatasets].filter(id=>available.has(id)));$('#main').innerHTML=head('数据管理','原始导入文件与待检查记录均保留在本机。',btn('导入数据','new','','primary'))+`<div class="selection-toolbar"><span><b id="data-selected-count">${selectedDatasets.size}</b> 份数据已选择</span><div>${btn('选择全部可删除数据','select-all-datasets')} ${btn('清空选择','clear-datasets')} ${btn('删除选中数据','bulk-delete-datasets',selectedDatasets.size?'':'disabled','danger')}</div></div><p class="muted batch-note">任务正在使用的数据不能删除。请先删除相关任务，再删除数据。</p><div class="panel flush"><div class="table-wrap"><table><thead><tr><th>选择</th><th>文件名</th><th>坐标系</th><th>总量</th><th>有效</th><th>异常</th><th>重复</th><th>使用情况</th><th>操作</th></tr></thead><tbody>${rows.map(d=>`<tr><td><input class="dataset-check" type="checkbox" data-action="toggle-dataset" data-id="${d.id}" aria-label="选择数据 ${esc(d.name)}" ${d.job_count?'disabled title="有任务正在使用"':''} ${selectedDatasets.has(d.id)?'checked':''}></td><td>${esc(d.name)}</td><td>${esc(d.crs||'待确认')}</td><td>${d.stats.total??'—'}</td><td>${d.stats.valid??'—'}</td><td>${d.stats.invalid??'—'}</td><td>${d.stats.duplicate??'—'}</td><td>${d.job_count?`${d.job_count} 个任务使用`:'可删除'}</td><td>${btn('查看异常','issues',`data-id="${d.id}"`,'small')} ${btn('批量添加为目标','as-targets',`data-id="${d.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">尚未导入数据</div>'}</div>`}
async function targetPage(){targets=await api('/targets');const available=new Set(targets.map(t=>t.id));selectedTargets=new Set([...selectedTargets].filter(id=>available.has(id)));const researchTargets=targets.filter(t=>!isBuiltinTarget(t));if(wizard.target_ids)wizard.target_ids=wizard.target_ids.filter(id=>researchTargets.some(t=>t.id===id));const counts=targets.reduce((a,t)=>(a[t.crs]=(a[t.crs]||0)+1,a),{});$('#main').innerHTML=head('研究地点',`${researchTargets.length} 个研究重点村${targets.length-researchTargets.length?` · ${targets.length-researchTargets.length} 个内置示例点已隔离`:''} · 修改地点不会改变已有任务结果。`,`<div>${btn('批量导入重点村','target-import-open','','primary')} ${btn('新增地点','target-new')}</div>`)+`<div class="selection-toolbar target-convert"><span>当前坐标系：${Object.entries(counts).map(([crs,n])=>`${crs} ${n} 个`).join('，')||'暂无地点'}</span><div><select id="target-crs-convert" aria-label="转换后的坐标系"><option value="">选择转换后的坐标系</option>${['WGS84','GCJ-02','BD-09'].map(c=>opt(c,c)).join('')}</select> ${btn('转换全部目标地点','convert-target-crs',targets.length?'':'disabled','primary')}</div></div><p class="muted batch-note">正式研究请导入“94重点村_最终数据.csv”，文件中的中文标题会自动识别。内置城市示例点只用于演示，创建研究任务时不会自动选入。</p><div class="notice">重点村使用文件中已确定的游客中心或导航入口坐标；原始字段保留在数据管理中。批量导入后先检查数量和坐标系，再创建任务。</div><div class="selection-toolbar"><span><b id="target-selected-count">${selectedTargets.size}</b> 个地点已选择</span><div>${btn('全选可删除地点','select-all-targets',targets.length?'':'disabled')} ${btn('清空选择','clear-targets')} ${btn('删除选中地点','bulk-delete-targets',selectedTargets.size?'':'disabled','danger')}</div></div><p class="muted batch-note">删除后无法撤销。仅从地点列表移除，不删除导入数据，不影响历史任务保存的地点快照。</p><div class="panel flush"><div class="table-wrap"><table><thead><tr><th>选择</th><th>名称</th><th>经度</th><th>纬度</th><th>坐标系</th><th>等级</th><th>导航入口</th><th>备注</th><th>操作</th></tr></thead><tbody>${targets.map(t=>`<tr class="${isBuiltinTarget(t)?'builtin-row':''}"><td><input class="target-check" type="checkbox" data-action="toggle-target" data-id="${t.id}" aria-label="选择地点 ${esc(t.name)}" ${selectedTargets.has(t.id)?'checked':''}></td><td>${esc(t.name)}${isBuiltinTarget(t)?'（内置示例）':''}</td><td>${t.lon}</td><td>${t.lat}</td><td>${esc(t.crs)}</td><td>${esc(t.category||'—')}</td><td>${esc(t.entrance_name||'—')}</td><td style="max-width:360px;white-space:normal">${esc(t.note||'')}</td><td>${btn('编辑','target-edit',`data-id="${t.id}"`,'small')} ${btn('删除','target-delete',`data-id="${t.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></div>`}
let targetImport=null;
function showTargetImport(){
 const d=targetImport;
 let body='<h2>批量导入目标地点</h2>';
 if(!d)body+=`<p>支持 Excel（.xlsx）或 CSV，最大 100 MB。第一行是表头；Excel 读取当前活动工作表，请将点位表设为活动表后保存。</p><p class="muted">建议包含名称、经度、纬度列。同一文件应使用同一种坐标系。文件上传后保留在“数据管理”中。<br><a href="/api/templates/destinations.xlsx">下载旅游目的地模板</a> · <a href="/api/templates/destinations.csv">CSV 模板</a></p><label>选择文件<input id="target-import-file" type="file" accept=".xlsx,.csv"></label>${btn('上传并选择数据列','target-import-upload','style="margin-top:20px"','primary')}`;
 else if(!d.stats)body+=`<p>${esc(d.name)}</p><p class="muted">正式文件“94重点村_最终数据.csv”会自动识别中文标题，例如“重点村编号”“最终路线经度（GCJ-02）”“最终路线纬度（GCJ-02）”“路线查询坐标系”；GCJ-02坐标直接用于高德查询，不要再次转换。原始字段会完整保留。</p><div class="grid">${[['point_id','编号（可选）'],['name','名称（可选）'],['lon','查询经度（优先最终导航坐标）'],['lat','查询纬度（优先最终导航坐标）'],['coordinate_system','坐标系（逐行填写时优先）'],['province','省（可选）'],['city','市（可选）'],['county','县区（可选）'],['village_name','村名（可选）'],['entrance_name','导航入口名称（可选）'],['coordinate_source','坐标来源（可选）'],['verification_status','是否可路由（可选）'],['category','地点等级 A/B/C（可选）'],['route_poi_type','导航地点类型（可选）'],['official_batch','公布批次（可选）'],['notes','备注或核验说明（可选）']].map(([key,label])=>`<label>${label}<select id="ti-${key}">${opt('','请选择',d.mapping[key]??'')}${d.columns.map((name,i)=>opt(i,name,d.mapping[key])).join('')}</select></label>`).join('')}<label>文件坐标系<select id="ti-crs">${opt('','请选择坐标系',d.crs||'')}${['WGS84','GCJ-02','BD-09'].map(c=>opt(c,c,d.crs)).join('')}</select></label></div><p class="muted">名称为空时使用编号；编号也为空时使用文件行号。若填写“坐标系”列，逐行值优先；空白行使用上面的文件坐标系。A/B/C只记录地点质量，不会进行机构分类或自动去重。</p>${btn('检查数据','target-import-check','','primary')}`;
 else body+=`<p>${esc(d.name)} · ${esc(d.crs)}</p><div class="notice">共 ${d.stats.total} 行，可导入 ${d.stats.valid} 行，坐标异常 ${d.stats.invalid} 行，含重复标记 ${d.stats.duplicate} 行。</div><p>仅添加有效坐标记录，异常行跳过。重复记录保留，不与已有目标自动去重；不会覆盖已有目标或改变已有任务。</p>${d.issues?.length?`<details><summary>查看异常或重复记录（前 20 条）</summary><ul>${d.issues.map(r=>`<li>第 ${r.row_no} 行：${esc(JSON.parse(r.issues).join('、'))}</li>`).join('')}</ul></details>`:''}<div class="toolbar" style="margin-top:20px">${btn('返回修改数据列','target-import-back')} ${btn('确认导入 '+d.stats.valid+' 个目标','target-import-commit',d.stats.valid?'':'disabled','primary')}</div>`;
 $('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();
}
function targetForm(t={}){$('#modal-body').innerHTML=`<h2>${t.id?'编辑':'新增'}目标地点</h2><p class="muted">可填写游客中心、景区入口等实际到达位置；不要把村委会坐标当作唯一入口。坐标系请按数据来源选择。</p><p id="target-error" class="error" role="alert" hidden></p><div class="form-stack"><label>目标名称<input id="t-name" value="${esc(t.name||'')}"></label><label>稳定目标 ID（可选）<input id="t-target-id" value="${esc(t.target_id||'')}"></label><div class="grid"><label>经度<input id="t-lon" type="number" step="any" min="-180" max="180" required placeholder="例如：114.240124" value="${t.lon??''}"></label><label>纬度<input id="t-lat" type="number" step="any" min="-90" max="90" required placeholder="例如：30.636285" value="${t.lat??''}"></label></div><label>坐标系<select id="t-crs">${['WGS84','GCJ-02','BD-09'].map(c=>opt(c,c,t.crs||'GCJ-02')).join('')}</select></label><div class="grid"><label>省<input id="t-province" value="${esc(t.province||'')}"></label><label>市<input id="t-city" value="${esc(t.city||'')}"></label><label>县区<input id="t-county" value="${esc(t.county||'')}"></label><label>村名<input id="t-village" value="${esc(t.village_name||'')}"></label></div><div class="grid"><label>入口名称<input id="t-entrance" value="${esc(t.entrance_name||'')}"></label><label>坐标来源<input id="t-coordinate-source" value="${esc(t.coordinate_source||'')}"></label><label>核验状态<input id="t-verification" value="${esc(t.verification_status||'')}"></label></div><label>备注<input id="t-note" value="${esc(t.note||'')}"></label>${btn('保存目标','target-save','data-id="'+(t.id||'')+'"','primary')}</div>`;$('#modal').showModal()}
async function settingsPage(){settings=await api('/settings');$('#main').innerHTML=head('系统设置','选择地图服务，并设置查询次数上限。')+`<div class="panel"><h2>地图服务</h2><div class="form-stack"><div class="grid"><label>默认地图服务<select id="s-provider">${opt('mock','模拟数据（仅供测试）',settings.provider)}${opt('amap','高德驾车路线',settings.provider)}</select></label><label>高德密钥（Web 服务 API Key）<input type="password" id="s-key" autocomplete="new-password" placeholder="${settings.has_key===null?'系统凭据库正在读取':settings.has_key?'已保存；留空表示不修改':'尚未配置'}"></label></div><label class="check"><input id="s-plain" type="checkbox">将新密钥保存在本机未加密文件中（仅在系统安全存储不可用时选择）</label><p class="muted">默认使用系统安全存储保存密钥。若选择未加密文件，密钥保护取决于本机文件权限，请勿共享该文件。</p><div class="grid"><label>每秒最多查询次数<input id="s-qps" type="number" min="0.1" max="20" step="0.1" value="${settings.qps}"></label><label>最大并发请求数<input id="s-concurrency" type="number" min="1" max="8" step="1" value="${settings.max_concurrency||3}"></label><label>每天最多查询次数（含重试）<input id="s-limit" type="number" min="1" value="${settings.daily_limit}"></label><label>最大自动重试次数<input id="s-retries" type="number" min="0" max="5" value="${settings.retries}"></label></div><div class="notice">请求启动QPS与并发数分别控制；每次请求都会保留尝试记录和原始响应索引。失败后会等待再试，达到每日上限后暂停。这里的上限仅约束本软件；账户剩余额度和费用请查看高德平台。</div><div>${btn('保存设置','save-settings','','primary')}</div></div></div><div class="panel"><h2>本地存储</h2><p>数据目录：<code>${esc(settings.data_dir)}</code></p><p class="muted">密钥保存方式：${esc(settings.key_storage)}。备份前先退出应用，再复制整个数据文件夹。系统安全存储中的密钥需另行配置。</p><p class="muted">研究任务默认不复用历史路线缓存；每个批次都会重新请求。历史结果只在原任务中查看，修改设置不会改变历史数据来源。</p></div>`}
async function usagePage(){const rows=await api('/usage');$('#main').innerHTML=head('地图查询记录','统计本软件发起的地图查询，包括失败和重试。模拟计算不计入。')+`<div class="panel flush"><div class="table-wrap"><table><thead><tr><th>日期 · 北京时间</th><th>地图服务</th><th>查询次数</th><th>错误次数</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.day)}</td><td>${esc(providerName(r.provider))}</td><td>${r.calls}</td><td>${r.errors}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">尚未查询地图。可以先用模拟模式体验功能。</div>'}</div>`}
async function exportFile(kind,includeRaw=true){toast(kind==='package'?(includeRaw?'正在生成含原始响应的研究数据包…':'正在生成不含原始响应的研究数据包…'):(kind==='paper'?'正在生成论文分析表…':kind==='quality'?'正在生成采集质量报告…':'正在生成 Excel…'));const params={...filters,kind};if(kind==='package')params.include_raw=String(includeRaw);const r=await fetch(`/api/jobs/${activeJob.id}/export?${new URLSearchParams(params)}`);if(!r.ok)throw Error((await r.json()).detail);const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const cd=r.headers.get('content-disposition')||'',match=cd.match(/filename\*=UTF-8''([^;]+)/i);a.download=match?decodeURIComponent(match[1]):`交通可达性_${kind}.${kind==='package'?'zip':'xlsx'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(kind==='package'?(includeRaw?'含原始响应的研究数据包已生成，开始下载':'不含原始响应的研究数据包已生成，开始下载'):kind==='paper'?'论文分析表已生成，开始下载':kind==='quality'?'采集质量报告已生成，开始下载':'Excel 已生成，开始下载')}
async function showSummary(){const dep=filters.departure||activeJob.config.departures[0],top=Number($('#summary-top')?.value||3);const rows=await api(`/jobs/${activeJob.id}/summary?${new URLSearchParams({departure:dep,top,page:summaryPage,od_direction:filters.od_direction||''})}`);$('#modal-body').innerHTML=`<h2>起点汇总${activeJob.config.collection_mode==='scheduled'?' · '+esc(dep):''}</h2><p class="muted">${activeJob.config.institution_summary?'按机构 ID 去重，使用成功入口的最短耗时；旧任务仍按原口径。':''} ${activeJob.config.mode==='saving'?'仅附近目标预筛选':'本任务所选目标'} · ${esc(types[activeJob.config.provider]||'高德当前路线估算')} · 仅统计成功结果；去程和返程分开统计 · 第 ${summaryPage} 页</p><div class="toolbar"><select id="summary-top">${[1,3,5,10].map(n=>opt(n,'显示前 '+n+' 名',top)).join('')}</select>${btn('更新排名','summary-update')}</div><div class="table-wrap"><table><thead><tr><th>方向</th><th>点位</th><th>直线距离最近</th><th>驾车时间排名</th><th>成功路线数</th><th>不同重点村数</th><th>1 / 2 / 3 / 4 小时内成功重点村数</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${s.direction==='inbound'?'返程':s.direction==='outbound'?'去程':'未区分'}</td><td>${esc(s.point_id)}<br>${esc(s.point_name)}</td><td>${esc(s.nearest_straight)}</td><td>${s.top.map(t=>`${esc(t.target_name)} · ${fmt(t.duration_seconds,60)} min`).join('<br>')||'—'}</td><td>${s.success_routes}</td><td>${s.distinct_targets}</td><td>${s.reachable['1']} / ${s.reachable['2']} / ${s.reachable['3']} / ${s.reachable['4']}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:16px">${btn('上一页','summary-prev',summaryPage===1?'disabled':'')} ${btn('下一页','summary-next',rows.length<50?'disabled':'')}</div>`;if(!$('#modal').open)$('#modal').showModal()}
const actions={
 'toggle-job':el=>{el.checked?selectedJobs.add(el.dataset.id):selectedJobs.delete(el.dataset.id);updateSelectionControls()},
 'select-all-jobs':()=>{document.querySelectorAll('.job-check:not(:disabled)').forEach(el=>{el.checked=true;selectedJobs.add(el.dataset.id)});updateSelectionControls()},
 'clear-jobs':()=>{selectedJobs.clear();document.querySelectorAll('.job-check').forEach(el=>el.checked=false);updateSelectionControls()},
 'bulk-delete-jobs':async()=>{if(!selectedJobs.size)throw Error('请先选择要删除的任务');if(confirm(`确定删除选中的 ${selectedJobs.size} 个任务及其计算结果吗？此操作无法撤销。`)){const r=await api('/jobs/bulk-delete','POST',{ids:[...selectedJobs]});selectedJobs.clear();await jobs();toast(`已删除 ${r.deleted} 个任务`)}},
 'toggle-dataset':el=>{el.checked?selectedDatasets.add(el.dataset.id):selectedDatasets.delete(el.dataset.id);updateSelectionControls()},
 'select-all-datasets':()=>{document.querySelectorAll('.dataset-check:not(:disabled)').forEach(el=>{el.checked=true;selectedDatasets.add(el.dataset.id)});updateSelectionControls()},
 'clear-datasets':()=>{selectedDatasets.clear();document.querySelectorAll('.dataset-check').forEach(el=>el.checked=false);updateSelectionControls()},
 'bulk-delete-datasets':async()=>{if(!selectedDatasets.size)throw Error('请先选择要删除的数据');if(confirm(`确定删除选中的 ${selectedDatasets.size} 份数据及其原始文件吗？此操作无法撤销。`)){const r=await api('/datasets/bulk-delete','POST',{ids:[...selectedDatasets]});selectedDatasets.clear();await dataPage();toast(r.message)}},
 'toggle-target':el=>{const id=Number(el.dataset.id);el.checked?selectedTargets.add(id):selectedTargets.delete(id);updateSelectionControls()},
 'select-all-targets':()=>{document.querySelectorAll('.target-check').forEach(el=>{el.checked=true;selectedTargets.add(Number(el.dataset.id))});updateSelectionControls()},
 'clear-targets':()=>{selectedTargets.clear();document.querySelectorAll('.target-check').forEach(el=>el.checked=false);updateSelectionControls()},
 'bulk-delete-targets':async el=>{if(!selectedTargets.size)throw Error('请先选择要删除的目标');if(!confirm(`确定删除选中的 ${selectedTargets.size} 个目标吗？删除后无法撤销。已有任务与导入数据不受影响。`))return;el.disabled=true;try{const r=await api('/targets/bulk-delete','POST',{ids:[...selectedTargets]});selectedTargets.clear();await targetPage();toast(`已删除 ${r.deleted} 个目标`)}finally{updateSelectionControls()}},
 'convert-target-crs':async()=>{const crs=$('#target-crs-convert').value;if(!crs)throw Error('请先选择转换后的坐标系');if(confirm(`将全部 ${targets.length} 个目标转换为 ${crs} 吗？系统会换算经纬度，已有任务不受影响。`)){const r=await api('/targets/convert-crs','POST',{crs});await targetPage();toast(`已将 ${r.converted} 个目标转换为 ${crs}；${r.unchanged} 个无需转换`) }},
 'new':async()=>{clearWizardDraft();wizard={step:1,times:'08:00',crs:'WGS84',mode:'exact',candidates:5,date:'',directions:['outbound'],source_point_ids:[],schedule:[],collection_mode:'immediate',schedule_template:'',schedule_adjusted:false,schedule_window_confirmed:false,data_use:'unmarked',estimate_seconds:0.75,window_minutes:30};location.hash='new';if(view==='new')await renderWizard()},
 'upload':async()=>{const file=$('#upload').files[0];if(!file)throw Error('请选择文件');const data=new FormData();data.append('file',file);const r=await api('/imports','POST',data);Object.assign(wizard,{dataset_id:r.id,columns:r.columns,mapping:r.mapping,stats:null,step:2,existing:false});if(r.mapping?.coordinate_system!==null&&r.mapping?.coordinate_system!==undefined)wizard.crs=r.crs||'GCJ-02';await renderWizard()},
'existing':async()=>{const ds=(await api('/datasets')).find(d=>d.id===$('#existing').value);wizard.dataset_id=ds.id;wizard.stats=ds.stats;wizard.crs=ds.crs;wizard.source_point_ids=[];wizard.step=3;wizard.existing=true;await renderWizard()},
'research-refresh':showResearch,'research-export':()=>exportFile('research'),
'validate':doValidate,'wizard-next':nextStep,'wizard-back':async()=>{wizard.step=wizard.existing&&(wizard.step===3||wizard.step===4)?1:wizard.step-1;await renderWizard()},
 'apply-formal-plan':async()=>{if((wizard.schedule||[]).length&&!confirm('重新填入7日最终锁定计划会覆盖当前采集草稿，是否继续？'))return;wizard.collection_mode='scheduled';wizard.schedule=formalPlanRows();wizard.schedule_template=FORMAL_TEMPLATE_VERSION;wizard.schedule_adjusted=false;wizard.schedule_window_confirmed=false;persistWizardDraft();await renderWizard()},
 'save-schedule-draft':async()=>{const rows=readScheduleRows();if(rows.length){wizard.schedule=rows;wizard.collection_mode='scheduled';wizard.schedule_window_confirmed=Boolean($('#window-confirmed')?.checked);const lockedCalendar=scheduleMatchesFormal(rows);wizard.schedule_template=lockedCalendar&&finalScopeMatches()?FORMAL_TEMPLATE_VERSION:'custom';wizard.schedule_adjusted=!lockedCalendar||!finalScopeMatches();persistWizardDraft();toast('采集计划草稿已保存；刷新页面后仍可继续编辑')}else throw Error('请先填入至少一个采集日')},
 'schedule-add':async()=>{const rows=readScheduleRows();wizard.schedule=[...rows,{phase:'自定义',day_type:'custom',date:'',times:['08:00'],window_minutes:30,directions:null,notes:''}];wizard.collection_mode='scheduled';persistWizardDraft();await renderWizard()},
 'schedule-remove':async el=>{const rows=readScheduleRows();const index=Number(el.dataset.index);if(rows.length<=1)throw Error('至少保留一个采集日；如不需要定时采集，请切换为立即采集');wizard.schedule=rows.filter((_,i)=>i!==index);persistWizardDraft();await renderWizard()},
'select-all':()=>document.querySelectorAll('input[name=target]').forEach(x=>x.checked=true),'select-none':()=>document.querySelectorAll('input[name=target]').forEach(x=>x.checked=false),
'select-all-sources':()=>document.querySelectorAll('input[name=source]').forEach(x=>x.checked=true),'select-none-sources':()=>document.querySelectorAll('input[name=source]').forEach(x=>x.checked=false),
'issues':async el=>{const r=await api(`/datasets/${el.dataset.id}/points?issues=true&size=200`);$('#modal-body').innerHTML=`<h2>异常与重复记录</h2><p class="muted">共 ${r.total} 条，显示前 200 条。原始数据保留，不自动删除。</p><div class="table-wrap"><table><thead><tr><th>行号</th><th>ID</th><th>名称</th><th>问题</th><th>原始行</th></tr></thead><tbody>${r.rows.map(p=>`<tr><td>${p.row_no}</td><td>${esc(p.point_id)}</td><td>${esc(p.name)}</td><td>${esc(JSON.parse(p.issues).join('、'))}</td><td>${esc(p.raw)}</td></tr>`).join('')}</tbody></table></div>`;$('#modal').showModal()},
'control':async el=>{await api(`/jobs/${activeJob.id}/${el.dataset.command}`,'POST');activeJob=await api('/jobs/'+activeJob.id);$('#job-progress').innerHTML=progressHTML(activeJob);await resultTable()},
'rename':async()=>{const name=prompt('任务名称',activeJob.name);if(name){await api('/jobs/'+activeJob.id,'PATCH',{name});await jobPage(activeJob.id)}},
'save-data-use':async()=>{const value=$('#job-data-use').value;await api('/jobs/'+activeJob.id,'PATCH',{name:activeJob.name,data_use:value});activeJob=await api('/jobs/'+activeJob.id);await jobPage(activeJob.id);toast('数据用途已保存；历史观测内容未改变')},
'delete-job':async()=>{if(confirm('删除任务及其结果？原始数据和可复用结果会保留。')){await api('/jobs/'+activeJob.id,'DELETE');location.hash='jobs'}},
'filter':async()=>{filters={q:$('#search').value,status:$('#filter-status').value,target:$('#filter-target').value,departure:$('#filter-time').value,od_direction:$('#filter-direction').value,sort:$('#sort').value};if($('#filter-hours').value)filters.hours=$('#filter-hours').value;page=1;await resultTable()},
'prev':async()=>{page--;await resultTable()},'next':async()=>{page++;await resultTable()},'logs':logTable,'export':()=>exportFile('details'),'export-paper':()=>exportFile('paper'),'export-quality':()=>exportFile('quality'),'export-summary':()=>exportFile('summary'),'export-package':()=>exportFile('package',true),'export-package-no-raw':()=>exportFile('package',false),
'summary':async()=>{summaryPage=1;await showSummary()},'summary-update':showSummary,'summary-prev':async()=>{summaryPage--;await showSummary()},'summary-next':async()=>{summaryPage++;await showSummary()},
'as-targets':async el=>{if(confirm('全部可计算记录添加为目标？重复记录也保留。')){await api(`/datasets/${el.dataset.id}/as-targets`,'POST');toast('目标已批量添加')}},
 'target-import-open':()=>{targetImport=null;showTargetImport()},
 'target-import-upload':async el=>{const file=$('#target-import-file').files[0];if(!file)throw Error('请先选择 Excel 或 CSV 文件');el.disabled=true;try{const form=new FormData();form.append('file',file);const r=await api('/imports','POST',form);targetImport={...r,name:file.name,crs:r.crs||''};showTargetImport()}finally{el.disabled=false}},
 'target-import-check':async el=>{const d=targetImport;d.crs=$('#ti-crs').value;if(!d.crs)throw Error('请选择文件的原始坐标系');for(const k of ['point_id','name','lon','lat','coordinate_system','province','city','county','village_name','entrance_name','coordinate_source','verification_status','category','route_poi_type','official_batch','notes']){const field=$('#ti-'+k);if(!field)continue;const v=field.value;d.mapping[k]=v===''?null:Number(v)}el.disabled=true;try{const stats=await api(`/imports/${d.id}/validate`,'POST',{mapping:d.mapping,crs:d.crs});const issues=await api(`/datasets/${d.id}/points?issues=true&size=20`);d.stats=stats;d.issues=issues.rows;showTargetImport()}finally{el.disabled=false}},
 'target-import-back':()=>{targetImport.stats=null;showTargetImport()},
 'target-import-commit':async el=>{const d=targetImport;if(!d?.stats?.valid||d.importing)return;d.importing=true;el.disabled=true;try{await api(`/datasets/${d.id}/as-targets`,'POST');targetImport=null;$('#modal').close();await targetPage();toast(`已导入 ${d.stats.valid} 个目标，跳过 ${d.stats.invalid} 行异常数据`)}finally{d.importing=false;el.disabled=false}},
 'target-new':()=>targetForm(),'target-edit':el=>targetForm(targets.find(t=>t.id===+el.dataset.id)),
 'target-delete':async el=>{if(confirm('删除目标？已有任务的结果不受影响。')){await api('/targets/'+el.dataset.id,'DELETE');await targetPage()}},
 'target-save':async el=>{const error=$('#target-error');error.hidden=true;for(const [id,label,bound] of [['t-lon','经度',180],['t-lat','纬度',90]]){const input=$('#'+id),v=Number(input.value);if(input.value.trim()===''||!Number.isFinite(v)||Math.abs(v)>bound){error.textContent=label+'必须是 -'+bound+' 到 '+bound+' 之间的数字，请检查小数点。';error.hidden=false;input.focus();return}}if(!$('#t-name').value.trim()){error.textContent='名称不能为空。';error.hidden=false;$('#t-name').focus();return}await api('/targets'+(el.dataset.id?'/'+el.dataset.id:''),el.dataset.id?'PUT':'POST',{name:$('#t-name').value,lon:+$('#t-lon').value,lat:+$('#t-lat').value,crs:$('#t-crs').value,note:$('#t-note').value,target_id:$('#t-target-id').value,province:$('#t-province').value,city:$('#t-city').value,county:$('#t-county').value,village_name:$('#t-village').value,entrance_name:$('#t-entrance').value,coordinate_source:$('#t-coordinate-source').value,verification_status:$('#t-verification').value});$('#modal').close();await targetPage()},
 'save-settings':async()=>{settings=await api('/settings','PUT',{provider:$('#s-provider').value,qps:+$('#s-qps').value,max_concurrency:+$('#s-concurrency').value,daily_limit:+$('#s-limit').value,retries:+$('#s-retries').value,api_key:$('#s-key').value,plaintext:$('#s-plain').checked,strategy:'32'});wizard.provider=settings.provider;wizard.providerDefault=settings.provider;$('#provider-badge').textContent=settings.provider==='mock'?'模拟模式 · 仅供测试':'高德 · 当前路线估算';toast('设置已保存，新建任务将默认使用'+providerName(settings.provider));await settingsPage()}
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||!actions[el.dataset.action])return;el.disabled=true;try{await actions[el.dataset.action](el)}catch(e){const box=$('#target-error');if(el.dataset.action==='target-save'&&box){box.textContent=e.message;box.hidden=false}else toast(e.message)}finally{if(el.isConnected)el.disabled=false}});
$('#exit').addEventListener('click',async()=>{if(confirm('退出应用？已完成结果保留，未完成任务下次可继续。')){try{await api('/shutdown','POST');$('#main').innerHTML=head('应用已退出','数据已保存在本机。再次双击应用即可继续。');view='closed'}catch(e){toast(e.message)}}});
document.addEventListener('change',e=>{if(e.target.id==='collection-mode'){wizard.collection_mode=e.target.value;const fields=$('#schedule-fields');if(fields)fields.hidden=e.target.value!=='scheduled';}});
window.addEventListener('hashchange',route);
async function poll(){try{if(view==='job'&&activeJob){const j=await api('/jobs/'+activeJob.id),changed=j.status!==activeJob.status;activeJob=j;if($('#job-progress'))$('#job-progress').innerHTML=progressHTML(j);if(changed&&$('#results'))await resultTable();if($('#research-report')&&(changed||(['queued','running','scheduled'].includes(j.status)&&Date.now()-lastReportRefresh>15000)))await showResearch()}if(view==='jobs'&&$('#job-list')){$('#job-list').innerHTML=jobTable(await api('/jobs'),true);updateSelectionControls()}}catch(e){}setTimeout(poll,2000)}
(async()=>{try{const version=await api('/version');if(version.version!=='2026.09.21.10')throw Error('应用版本已更新，请退出应用并重新打开');settings=await api('/settings');$('#provider-badge').textContent=settings.provider==='mock'?'模拟模式 · 仅供测试':'高德 · 当前路线估算';await route();poll()}catch(e){toast(e.message)}})();
